  async createWorkflowRun(insertRun: InsertWorkflowRun) {
    return db.transaction(async tx => {
      if (!insertRun.workflowId) throw new WorkflowCommandError("Workflow unavailable", 404);
      const [wf] = await tx.select().from(workflows).where(eq(workflows.id, insertRun.workflowId)).for("update");
      if (!wf || wf.retiredAt || !wf.enabled) throw new WorkflowCommandError("Workflow disabled or retired; no run was claimed", 409);
      const [run] = await tx.insert(workflowRuns).values(insertRun).returning();
      return run;
    });
  }


